window.assertive = {
    entityId: "wnsrvBJmEPrTfrnFX",
    analytics: {
        sampleRate: 0.05,
        integrations: {
            ivt: false,
            taboola: false,
            reconciliation: false,
        },
        custom: {},
        logUnfilled: true,
        useHistoryChangeTrigger: true,
        override: {
            normalizeSlotId: function (slotId) {
                return slotId.replace(
                    /-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/,
                    ""
                );
            },
        },
    },
    floor: {
        enabled: true,
        addToHashKey: false,
        currency: "USD",
        thresholds: [
            '1st_1.2',
            '1st_1.3',
            '1st_1.4',
            '1st_1.5',
            '1st_1.6',
            '1st_1.7',
            '1st_1.8',
            'm_0.1',
            'm_0.2',
            'm_0.3',
            'm_0.4',
            'm_0.5',
            'q_2',
            'q_3',
            'q_4',
            'q_5',
        ],
        optimizeThreshold: '1st_1.5',
        optimizePrebidThreshold: '1st_1.4',
        exploreRate: 0.05,
        limit: {
            percentage: 0.95,
        },
        prebid: true,
        aps: false,
        priceBuckets: [
            { min: 0, max: 2, increment: 0.01 },
            { min: 2, max: 3, increment: 0.05 },
        ],
    },
    viewability: {
        enabled: true,
    }
};
window.assertiveQueue = window.assertiveQueue || [];

window.addEventListener('assertive_logImpression', function(event) {
    var payload = event.data.payload;
    var split = (payload.adUnitPath || '').split('/');
    if (split.length > 3) {
        payload.layout = split[3];
    }

    if (payload.dfpTargetingMap && payload.dfpTargetingMap.pstaid) {
        payload.custom_4 = payload.dfpTargetingMap.pstaid[0];
    }
});

window.googletag = window.googletag || {};
window.googletag.cmd = window.googletag.cmd || [];
googletag.cmd.push(function() {
    googletag.pubads().setTargeting('ay_hb_house', '1');
    var pstaid = googletag.pubads().getTargeting('pstaid');
    if (pstaid && pstaid.length > 0) {
        assertive.analytics.custom.custom_4 = pstaid[0];
    }
});

(function() {
    try {
        var domain = window.location.hostname.replace('www.', '');
        if (domain === 'engadget.com') {
            assertive.analytics.sampleRate = 1;
        }

        var isMail = domain === 'gpt.mail.yahoo.net';
        var ra = Math.random();
        var percentageGeneral = 0.5;
        var percentageMail = 0.02;
        if ((!isMail && ra <= percentageGeneral) || (isMail && ra <= percentageMail)) {
            let path = '';
            const positions = Object.keys((window.benji && benji.config && benji.config.positions) || {});
            if (positions.length) {
                path = benji.config.positions[positions[0]].path || '';
            }
            assertive.floor.exploreRate = 'auto';
            assertive.floor.adUnitPath = path;
            delete assertive.floor.limit;
            
            /* assertive.floor.priceBuckets = [
                { min: 0, max: 2, increment: 0.01 },
                { min: 2, max: 3, increment: 0.05 },
                // { min: 2, max: 3, increment: 0.02 },
                { min: 2, max: 6, increment: 0.02 },
                { min: 6, max: 10, increment: 0.10 },
                { min: 10, max: 15.10, increment: 0.30 },
            ]; */
        }
    } catch (e) {
        console.error(e);
    }
})();

window.assertiveQueue.push(function() {
    var buckets = [];
    window.pbjs = window.pbjs || {};
    window.pbjs.que = window.pbjs.que || [];
    pbjs.que.push(function() {
        pbjs.requestBids.before(function (next, reqBidsConfigObj) {
            try {
                if (typeof assertive.analytics.custom.custom_1 === 'string' && !buckets.length) {
                    buckets = assertive.analytics.custom.custom_1.split(',');
                }

                const adUnitCodes = reqBidsConfigObj.adUnitCodes || [];
                reqBidsConfigObj.adUnits.forEach(function(bidRequest) {
                    if (!adUnitCodes.length || adUnitCodes.includes(bidRequest.code)) {
                        if (
                            bidRequest.mediaTypes && bidRequest.mediaTypes.video &&
                            bidRequest.mediaTypes.video.context === 'outstream' &&
                            bidRequest.floors && bidRequest.floors.values
                        ) {
                            const floor = bidRequest.floors.values['*'] || 0;
                            if (floor) {
                                bidRequest.floors.values['video'] = floor * 1.25;
                            }
                        }
                    }
                });
            } catch (e) {
                window.assertiveQueue.push(function () {
                    assertive.logError('Outstream floor multiplier failed!', e, { source: 'script' });
                });
            }
            next.apply(this, [reqBidsConfigObj]);
        }, 60);
    });
});
